// FILE PATH: lib/supabase.ts
import { createClient } from '@supabase/supabase-js';

const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL || '';
const supabaseAnonKey = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY || '';

export const supabase = supabaseUrl && supabaseAnonKey 
  ? createClient(supabaseUrl, supabaseAnonKey) 
  : null;

export type UserRole = 'admin' | 'working_member' | 'member' | 'visitor';

export interface StudioUser {
  id: string;
  email: string;
  password?: string;
  role: UserRole;
  name: string;
  clearanceCode: string;
  createdAt: string;
}

export interface StudioTask {
  id: string;
  title: string;
  assignedTo: string; // email
  status: 'QUEUED' | 'ACTIVE' | 'DEPLOYED';
  priority: 'CRITICAL' | 'HIGH' | 'NOMINAL';
  dueDate: string;
}

export interface StudioLead {
  id: string;
  clientName: string;
  company: string;
  scope: string;
  budget: string;
  addedBy: string;
  status: 'INITIAL_CONTACT' | 'ARCH_REVIEW' | 'LOCKED';
}

export interface CustomSheet {
  id: string;
  name: string;
  columns: string[];
  rows: Record<string, string>[];
}

